<?php
declare(strict_types=1);
require_once __DIR__ . '/../../app/bootstrap.php'; require_once __DIR__ . '/../../app/read_queries.php'; require_once __DIR__ . '/../../app/operational_writes.php';
$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$action=(string)($_GET['accion']??'');$permissions=['parada'=>'VIAJES_PARADAS','asignar'=>'VIAJES_ASIGNAR','iniciar'=>'VIAJES_INICIAR','finalizar'=>'VIAJES_FINALIZAR'];if($id===false||!isset($permissions[$action])){http_response_code(404);exit('Acción no disponible.');}require_permission($permissions[$action]);try{$sets=read_procedure_sets('EXEC dbo.sp_obtener_viaje @viaje_id=?;',[(int)$id]);$viaje=$sets[0][0]??null;$paradas=$sets[1]??[];}catch(PDOException){read_error_response();}if(!is_array($viaje)){http_response_code(404);exit('Viaje no encontrado.');}$valid=($action==='finalizar'?$viaje['estado']==='EN_CURSO':$viaje['estado']==='PLANIFICADO');if(!$valid){http_response_code(409);exit(ui_notice('El viaje ya no admite esta acción.','warning'));}
if($action==='parada'){try{$ubicaciones=operation_list('DECLARE @total_registros INT; EXEC dbo.sp_listar_ubicaciones @buscar=NULL,@solo_activos=1,@pagina=1,@por_pagina=100,@total_registros=@total_registros OUTPUT; SELECT @total_registros AS total_registros;');}catch(PDOException){read_error_response();}}if($action==='asignar'){try{$registradas=operation_list('DECLARE @total_registros INT; EXEC dbo.sp_listar_solicitudes @buscar=NULL,@estado=?,@cliente_id=NULL,@desde=NULL,@hasta=NULL,@pagina=1,@por_pagina=100,@total_registros=@total_registros OUTPUT; SELECT @total_registros AS total_registros;',['REGISTRADA']);$pendientes=operation_list('DECLARE @total_registros INT; EXEC dbo.sp_listar_solicitudes @buscar=NULL,@estado=?,@cliente_id=NULL,@desde=NULL,@hasta=NULL,@pagina=1,@por_pagina=100,@total_registros=@total_registros OUTPUT; SELECT @total_registros AS total_registros;',['PENDIENTE_ASIGNACION']);$solicitudes=array_merge($registradas,$pendientes);}catch(PDOException){read_error_response();}}
?>
<div class="modal is-active" role="dialog" aria-modal="true" aria-labelledby="titulo-viaje-accion"><div class="modal-background" data-close-modal></div><div class="modal-card"><header class="modal-card-head"><p class="modal-card-title" id="titulo-viaje-accion"><?= ['parada'=>'Agregar parada','asignar'=>'Asignar solicitud','iniciar'=>'Iniciar viaje','finalizar'=>'Finalizar viaje'][$action] ?></p><button class="modal-close icon-button" type="button" aria-label="Cerrar" data-close-modal><?= svg_icon('close') ?></button></header><form hx-post="/viajes/accion.php" hx-target="#mensaje-viaje-accion" hx-swap="innerHTML" hx-disabled-elt="find button[type=submit]"><section class="modal-card-body"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="viaje_id" value="<?= (int)$id ?>"><input type="hidden" name="accion" value="<?= e($action) ?>"><div id="mensaje-viaje-accion" role="alert"></div><p><strong><?= e($viaje['codigo_viaje']) ?></strong> · <?= status_tag($viaje['estado']) ?></p><?php if($action==='parada'):?><div class="field"><label class="label" for="parada-ubicacion">Ubicación</label><div class="select is-fullwidth"><select id="parada-ubicacion" name="ubicacion_id" required><option value="">Selecciona</option><?php foreach($ubicaciones as $row):?><option value="<?= (int)$row['ubicacion_id'] ?>"><?= e($row['nombre']) ?></option><?php endforeach;?></select></div></div><div class="columns"><div class="column"><div class="field"><label class="label" for="parada-orden">Orden</label><input class="input" id="parada-orden" name="orden" type="number" min="1" value="<?= count($paradas)+1 ?>" required></div></div><div class="column"><div class="field"><label class="label" for="parada-tipo">Tipo</label><div class="select is-fullwidth"><select id="parada-tipo" name="tipo_parada" required><option>RECOGIDA</option><option>ENTREGA</option><option>MIXTA</option><option>INTERMEDIA</option></select></div></div></div></div><?php elseif($action==='asignar'):?><div class="field"><label class="label" for="asignar-solicitud">Solicitud elegible</label><div class="select is-fullwidth"><select id="asignar-solicitud" name="solicitud_id" required><option value="">Selecciona</option><?php foreach($solicitudes as $row):?><option value="<?= (int)$row['solicitud_id'] ?>"><?= e($row['codigo_solicitud'].' · '.$row['estado']) ?></option><?php endforeach;?></select></div></div><div class="columns"><div class="column"><div class="field"><label class="label" for="parada-recogida">Parada de recogida</label><div class="select is-fullwidth"><select id="parada-recogida" name="parada_recogida_id" required><option value="">Selecciona</option><?php foreach($paradas as $row):?><option value="<?= (int)$row['parada_id'] ?>"><?= (int)$row['orden'] ?> · <?= e($row['ubicacion_nombre'].' · '.$row['tipo_parada']) ?></option><?php endforeach;?></select></div></div></div><div class="column"><div class="field"><label class="label" for="parada-entrega">Parada de entrega</label><div class="select is-fullwidth"><select id="parada-entrega" name="parada_entrega_id" required><option value="">Selecciona</option><?php foreach($paradas as $row):?><option value="<?= (int)$row['parada_id'] ?>"><?= (int)$row['orden'] ?> · <?= e($row['ubicacion_nombre'].' · '.$row['tipo_parada']) ?></option><?php endforeach;?></select></div></div></div></div><p class="help">SQL Server valida que las paradas correspondan a origen, destino y orden de la solicitud.</p><?php else:?><p><?= $action==='iniciar'?'Se iniciará el viaje sólo si ya tiene solicitudes asignadas.':'Se finalizará sólo cuando todas las solicitudes tengan un resultado terminal.' ?></p><?php endif;?></section><footer class="modal-card-foot"><div class="buttons"><button class="button <?= $action==='finalizar'?'is-danger is-light':'is-primary' ?>" type="submit"><?= $action==='parada'?'Agregar':($action==='asignar'?'Asignar':($action==='iniciar'?'Iniciar':'Finalizar')) ?></button><button class="button button-secondary" type="button" data-close-modal>Cancelar</button></div></footer></form></div></div>
